from __future__ import annotations

import importlib.util
import sys
from pathlib import Path

import pytest

API_TEST_DIR = Path(__file__).resolve().parent
if str(API_TEST_DIR) not in sys.path:
    sys.path.insert(0, str(API_TEST_DIR))


def _load_api_test_conftest():
    spec = importlib.util.spec_from_file_location(
        "api_test_bootstrap_conftest",
        API_TEST_DIR / "conftest.py",
    )
    if spec is None or spec.loader is None:
        raise RuntimeError("failed to load tests/api_test/conftest.py")

    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


api_conftest = _load_api_test_conftest()


class FakeResponse:
    def __init__(self, status_code: int, body: dict | None = None):
        self.status_code = status_code
        self._body = body or {}
        self.text = str(self._body)

    def json(self):
        return self._body


class FakeRootClient:
    def __init__(
        self,
        *,
        list_responses: list[FakeResponse],
        create_responses: list[FakeResponse] | None = None,
        register_responses: list[FakeResponse] | None = None,
    ):
        self.list_responses = list(list_responses)
        self.create_responses = list(create_responses or [])
        self.register_responses = list(register_responses or [])

    def admin_list_users(self, account_id: str):
        return self.list_responses.pop(0)

    def admin_create_account(self, account_id: str, user_id: str):
        return self.create_responses.pop(0)

    def admin_register_user(self, account_id: str, user_id: str, role: str):
        return self.register_responses.pop(0)

    def admin_set_role(self, account_id: str, user_id: str, role: str):
        return FakeResponse(200, {"status": "ok"})

    def admin_regenerate_key(self, account_id: str, user_id: str):
        return FakeResponse(200, {"result": {"user_key": "regenerated-key"}})


def _users_response(user_id: str = "default", api_key: str = "user-key") -> FakeResponse:
    return FakeResponse(
        200,
        {"result": [{"user_id": user_id, "role": "admin", "api_key": api_key}]},
    )


def test_register_conflict_reuses_concurrently_created_user_key(monkeypatch):
    monkeypatch.setattr(api_conftest.time, "sleep", lambda _seconds: None)
    root_client = FakeRootClient(
        list_responses=[
            FakeResponse(200, {"result": []}),
            _users_response(api_key="race-user-key"),
        ],
        register_responses=[FakeResponse(409, {"error": {"code": "ALREADY_EXISTS"}})],
    )

    assert (
        api_conftest._ensure_api_test_user_key(root_client, "default", "default") == "race-user-key"
    )


def test_create_account_conflict_reuses_concurrently_created_user_key(monkeypatch):
    monkeypatch.setattr(api_conftest.time, "sleep", lambda _seconds: None)
    root_client = FakeRootClient(
        list_responses=[
            FakeResponse(404, {"error": {"code": "NOT_FOUND"}}),
            _users_response(api_key="created-by-peer-key"),
        ],
        create_responses=[FakeResponse(409, {"error": {"code": "ALREADY_EXISTS"}})],
    )

    assert (
        api_conftest._ensure_api_test_user_key(root_client, "default", "default")
        == "created-by-peer-key"
    )


def test_refuses_to_fall_back_to_root_key(monkeypatch):
    monkeypatch.setattr(api_conftest.Config, "OPENVIKING_API_KEY", "root-key")
    monkeypatch.setattr(api_conftest.Config, "OPENVIKING_ROOT_API_KEY", "root-key")
    root_client = FakeRootClient(
        list_responses=[FakeResponse(500, {"error": {"code": "SERVER_ERROR"}})]
    )

    with pytest.raises(RuntimeError, match="refusing to fall back to the ROOT API key"):
        api_conftest._ensure_api_test_user_key(root_client, "default", "default")

import assert from 'node:assert/strict'
import test from 'node:test'

import {
  enrichSearchResultsWithLocalTitles,
  localizeSearchResultTitles
} from './openviking-search-results.ts'

test('uses the localized docs index title for Chinese remote results', () => {
  const results = enrichSearchResultsWithLocalTitles(
    [
      {
        relativePath: 'agent-integrations/08-community-plugins.md',
        snippet: '这是一份面向 OpenViking 使用者的社区插件参考文档。',
        title: 'Community Plugins',
        url: '/zh/agent-integrations/08-community-plugins'
      }
    ],
    [
      {
        locale: 'zh',
        path: 'zh/agent-integrations/08-community-plugins.md',
        text: '社区插件',
        title: '社区插件',
        url: '/zh/agent-integrations/08-community-plugins'
      }
    ],
    'zh'
  )

  assert.equal(results[0].title, '社区插件')
})

test('keeps remote results when local title lookup fails', async () => {
  const remoteResults = [
    {
      relativePath: 'agent-integrations/08-community-plugins.md',
      snippet: 'remote snippet',
      title: 'Community Plugins',
      url: '/zh/agent-integrations/08-community-plugins'
    }
  ]

  const results = await localizeSearchResultTitles(
    remoteResults,
    'zh',
    async () => {
      throw new Error('local index unavailable')
    }
  )

  assert.deepEqual(results, remoteResults)
})

import assert from 'node:assert/strict'
import test from 'node:test'

import {
  exampleLanguage,
  responseExample,
  isApiReferencePath,
  isSharedSectionLabel,
  preferredLanguage,
  shouldSynchronizeExampleTabs
} from './api-example-tabs.ts'
import { absoluteLlmsTxtUrl, hasPageLlmsTxt, pageLlmsTxtPath } from './llms-txt.ts'

test('hides llms.txt actions on index pages without generated artifacts', () => {
  assert.equal(hasPageLlmsTxt('index.md'), false)
  assert.equal(hasPageLlmsTxt('en/index.md'), false)
  assert.equal(hasPageLlmsTxt('zh/index.md'), false)
  assert.equal(hasPageLlmsTxt('en/api/01-overview.md'), true)
})

test('builds the absolute per-page llms.txt link copied by the page action', () => {
  const path = pageLlmsTxtPath('zh/guides/03-cli-config.md')
  assert.equal(path, '/zh/guides/03-cli-config/llms.txt')
  assert.equal(
    absoluteLlmsTxtUrl(`/OpenViking${path}`, 'https://docs.openviking.net'),
    'https://docs.openviking.net/OpenViking/zh/guides/03-cli-config/llms.txt'
  )
})

test('recognizes language headings with punctuation and qualifiers', () => {
  assert.equal(exampleLanguage('HTTP API：')?.key, 'http')
  assert.equal(exampleLanguage('CLI (subcommands of resources)')?.key, 'cli')
})

test('recognizes transport and result response variants', () => {
  assert.deepEqual(responseExample('HTTP API 响应 (JSON, `wait=true`)'), {
    key: 'response-http', label: 'HTTP (wait=true)', kind: 'response'
  })
  assert.equal(responseExample('CLI 响应 (JSON 格式，使用 -o json)')?.label, 'CLI JSON')
  assert.equal(responseExample('Response (Directory)')?.label, 'Directory')
  assert.equal(responseExample('响应（Memory）')?.label, 'Memory')
  assert.equal(responseExample('异步响应（`wait=false`）')?.key, 'response-async')
})

test('keeps localized response variant keys distinct', () => {
  const file = responseExample('响应（文件）')
  const directory = responseExample('响应（目录）')
  const importing = responseExample('响应示例（资源导入进行中）')
  const completed = responseExample('响应示例（完成）')

  assert.equal(file?.key, 'response-文件')
  assert.equal(directory?.key, 'response-目录')
  assert.notEqual(file?.key, directory?.key)
  assert.notEqual(importing?.key, completed?.key)
})

test('synchronizes language tabs without resetting response tabs', () => {
  assert.equal(shouldSynchronizeExampleTabs('language'), true)
  assert.equal(shouldSynchronizeExampleTabs('response'), false)
  assert.equal(shouldSynchronizeExampleTabs(undefined), false)
})

test('recognizes response and note variants as shared sections', () => {
  for (const label of [
    'Response',
    'Response Examples',
    'Result fields',
    'Error Response',
    'CLI override flags',
    'MCP (agent control plane)',
    'Notes:',
    '返回字段说明',
    '说明：'
  ]) {
    assert.equal(isSharedSectionLabel(label), true, label)
  }
  for (const label of [
    'Python SDK (Embedded / HTTP)',
    'TypeScript SDK',
    'Go SDK',
    'HTTP API',
    'CLI (via ovcli.conf)',
    'Response (File)',
    'HTTP API Response (JSON)',
    '响应（applied）',
    '响应示例（完成）'
  ]) {
    assert.equal(isSharedSectionLabel(label), false, label)
  }
  for (const label of [
    'Basic Search',
    'Image Search',
    'Search with Target URI Limitation',
    '基础搜索',
    '图片搜索',
    '使用 Target URI 限定搜索范围'
  ]) {
    assert.equal(isSharedSectionLabel(label), false, label)
  }
})

test('limits enhancement to localized API reference pages', () => {
  assert.equal(isApiReferencePath('/en/api/03-filesystem'), true)
  assert.equal(isApiReferencePath('/zh/api/04-skills'), true)
  assert.equal(isApiReferencePath('/OpenViking/en/api/11-snapshot'), true)
  assert.equal(isApiReferencePath('/en/guides/04-authentication'), false)
})

test('keeps one initial language across all groups', () => {
  assert.equal(preferredLanguage(null, undefined, 'typescript'), 'typescript')
  assert.equal(preferredLanguage(null, 'typescript', 'python'), 'typescript')
  assert.equal(preferredLanguage('go', 'typescript', 'python'), 'go')
})
